(()=>{'use strict';let batch=null,loading=false,polling=false,skipExisting=true;const active=()=>batch?.project_id===data.project_id&&batch.status==='running';
function mount(){if(!document.querySelector('#firstFrameGallery')&&(tab!==3||!document.querySelector('#shotConnections')))return;const head=document.querySelector('#panel .section-head');if(!head)return;const existing=[...document.querySelectorAll('#allFirstFrames')];existing.slice(1).forEach(el=>el.remove());if(existing.length){paint();return;}const box=document.createElement('div');box.id='allFirstFrames';box.style.cssText='display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:12px 0 20px';box.innerHTML='<button type="button" class="primary" data-first-batch-start>生成全部首帧</button><label style="display:flex;align-items:center;gap:7px;margin:0;white-space:nowrap"><input type="checkbox" data-first-batch-skip checked style="width:18px;height:18px;margin:0">跳过已生成</label><button type="button" data-first-batch-stop hidden>停止</button><span data-first-batch-progress></span>';head.after(box);const skip=box.querySelector('[data-first-batch-skip]');skip.checked=skipExisting;skip.onchange=()=>{skipExisting=skip.checked};box.querySelector('[data-first-batch-start]').onclick=start;box.querySelector('[data-first-batch-stop]').onclick=async()=>{try{batch=await frontFetch('/api/first-frame-batch/stop',{id:batch.id});paint()}catch(e){toast(e.message)}};paint()}
function paint(){const box=document.querySelector('#allFirstFrames');if(!box)return;box.querySelector('[data-first-batch-start]').disabled=loading||active();box.querySelector('[data-first-batch-skip]').disabled=loading||active();box.querySelector('[data-first-batch-stop]').hidden=!active();const label=box.querySelector('[data-first-batch-progress]');if(batch?.project_id!==data.project_id){label.textContent='';return;}const es=batch.entries||[],done=es.filter(e=>e.status==='completed').length,skip=es.filter(e=>e.status==='skipped').length,current=es.find(e=>e.status==='preparing_frames');label.textContent=(active()?'正在生成':batch.status==='completed'?'已完成':batch.status==='stopped'?'已停止':'已暂停')+' · '+(done+skip)+' / '+es.length+' · 新生成 '+done+' · 跳过 '+skip+(current?' · '+current.target_id:'')+(batch.error?' · '+batch.error:'');}
async function start(){if(loading||active())return;loading=true;paint();try{if(typeof videoBatchActive==='function'&&videoBatchActive())throw Error('请先停止视频批量任务');await flushDisk();if(diskConflict||diskBusy)throw Error('项目正在保存或已有更新，请稍后重试');const port=videoGenerationPort(),items=data.shots.map(s=>{const plan=shotFramePlan(s,'first'),refs=shotResolvedReferences(s),tags=plan.reference_tags||refs.map(r=>r.picture),[width,height]=ShotAspect.frame(s,data).split('x').map(Number);return{target_id:s.shot_id||s.id,position:'first',method:ShotMethods.imageMethod(s,'first'),prompt:plan.prompt,negative_prompt:plan.negative_prompt||'',width,height,reference_source:plan.reference_source||'picture_inputs',prompt_enhance:false,picture_inputs:refs.filter(r=>tags.includes(r.picture)).map(r=>({picture:r.picture,original_picture:r.picture,type:r.type,ref_id:r.ref_id,image_url:plan.fixed_reference_image?.picture===r.picture?plan.fixed_reference_image.image_url:r.item?.url||''}))}});batch=await frontFetch('/api/first-frame-batch',{project_id:data.project_id,port,items,skip_existing:skipExisting});toast(skipExisting?'已开始补齐首帧，跳过已生成':'已开始重新生成全部首帧');}catch(e){toast(e.message)}finally{loading=false;paint()}}
async function poll(){if(polling||!data.project_id)return;polling=true;const id=data.project_id;try{const r=await fetch('/api/first-frame-batch?project_id='+encodeURIComponent(id),{cache:'no-store'});if(!r.ok)return;const b=await r.json();if(data.project_id!==id)return;const changed=JSON.stringify(b)!==JSON.stringify(batch);batch=b;if(changed&&batch&&diskReady&&!diskBusy&&!diskConflict&&JSON.stringify(data)===lastDiskData){const remote=await(await fetch('/api/project?id='+encodeURIComponent(id),{cache:'no-store'})).json();if(data.project_id===id&&!diskBusy&&!diskConflict&&JSON.stringify(data)===lastDiskData&&remote.revision>diskRevision){data=remote.project;diskRevision=remote.revision;lastDiskData=JSON.stringify(data);browserSave();}}paint();}catch{}finally{polling=false}}
window.FirstFrameBatchUI={mount,status:()=>batch};const oldStage=stage;stage=function(){oldStage();mount()};setInterval(()=>{mount();if(tab===3||document.querySelector('#firstFrameGallery')||active())void poll()},2500);mount();void poll();})();
